import 'package:flutter/material.dart';
import 'package:talkiepal/practice/ai_practice_page.dart';
import 'package:talkiepal/widgets/level_menu_page.dart';

class PreIntermediatePage extends StatelessWidget {
  const PreIntermediatePage({super.key});

  static const LevelTheme _theme = LevelTheme(
    letter: 'B',
    title: 'Pre Intermediate',
    color: Color(0xFF42A5F5),
    darkColor: Color(0xFF1565C0),
    lightColor: Color(0xFF90CAF9),
    dinoColor: Color(0xFF7EC3F2),
  );

  // Topics whose practice phrases are generated by the AI backend.
  static const Map<String, String> _aiTopics = {
    'My Morning Routine': '🌅',
    'My Feelings': '😊',
    'Things I Like': '❤️',
    'School & Classroom': '🏫',
    'Hobbies & Free Time': '⚽',
    'Daily Routine': '⏰',
    'Home & Rooms': '🏠',
    'Shopping & Toys': '🧸',
  };

  /// Every topic of this level, as named on the results screen.
  static List<String> get topics => _aiTopics.keys.toList();

  @override
  Widget build(BuildContext context) {
    return LevelMenuPage(
      theme: _theme,
      dinoMessage: "Let's join words together and make short phrases!",
      sections: [
        LevelSection(
          topics: [
            for (final topic in _aiTopics.entries)
              LevelTopic(
                emoji: topic.value,
                title: topic.key,
                onTap: (context) => Navigator.push(
                  context,
                  MaterialPageRoute(
                    builder: (context) => AiPracticePage(
                      level: 'pre_intermediate',
                      levelLabel: 'Pre Intermediate',
                      topic: topic.key,
                      topicEmoji: topic.value,
                    ),
                  ),
                ),
              ),
          ],
        ),
      ],
    );
  }
}
